"""Preambulo de la version ejecutable del notebook consolidado.

Vive aparte porque es el unico que obtiene el proyecto por su cuenta: asi el
notebook funciona con «ejecutar todas», sin montar Drive ni subir archivos, tanto
en Colab como en un Jupyter local.
"""

from scripts.notebooks_contenido import code, md

PREAMBULO_FINAL_COLAB = [
    md('\n## Cómo ejecutar este notebook\n\n**En Google Colab**, que es lo más sencillo porque no hay que instalar nada:\n\n1. Entra en [colab.research.google.com](https://colab.research.google.com) con una\n   cuenta de Google.\n2. **Archivo → Subir notebook** y elige este archivo.\n3. Colab avisará de que *el notebook no lo creó Google*. Es normal al abrir un archivo\n   propio: pulsa **«Ejecutar de todos modos»**.\n4. **Entorno de ejecución → Ejecutar todas.**\n\nTarda menos de un minuto. La primera celda descarga el proyecto —código, datos ya\ncalculados y figuras— y el resto son lecturas, así que no hay esperas largas.\n\n**No hace falta instalar nada ni reiniciar el entorno.** El notebook solo usa `pandas`,\n`numpy` e `IPython`, que Colab ya trae.\n\nTambién se puede ejecutar celda por celda, en orden, con el botón de reproducir de cada\nuna. Y funciona en un Jupyter local: si el proyecto no está a mano, lo clona.\n\n> Si algo falla, casi siempre es por falta de conexión: la primera celda necesita\n> internet para descargar el proyecto.\n'),
    code('\n# 1/2 - El proyecto: codigo, datos ya calculados y figuras.\n#\n# Busca el proyecto en este orden: la carpeta actual (si ya estas dentro del\n# repositorio), un clon del repositorio publico, y solo en Colab y como ultimo recurso,\n# una copia en Drive o un .zip subido a mano. Los dos ultimos piden intervencion, asi\n# que rompen el «ejecutar todas»; el clon no.\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nREPOSITORIO = "https://github.com/JLosada-Dev/topicos-popayan.git"\nCARPETA_EN_DRIVE = "MyDrive/topicos-popayan"\n\n\ndef _en_colab() -> bool:\n    try:\n        import google.colab  # noqa: F401\n    except ImportError:\n        return False\n    return True\n\n\nDESTINO = Path("/content/topicos-popayan") if _en_colab() else Path("topicos-popayan")\n\n\ndef _sirve(raiz) -> bool:\n    raiz = Path(raiz)\n    return ((raiz / "src" / "config.py").exists()\n            and (raiz / "data" / "processed" / "fragmentos.csv").exists())\n\n\ndef _desde_drive():\n    from google.colab import drive\n\n    drive.mount("/content/drive", force_remount=False)\n    candidata = Path("/content/drive") / CARPETA_EN_DRIVE\n    return candidata if _sirve(candidata) else None\n\n\ndef _desde_zip():\n    import zipfile\n\n    from google.colab import files\n\n    print("Sube un .zip del proyecto (debe incluir src/ y data/processed/)")\n    subidos = files.upload()\n    carpeta = Path("/content/subido")\n    with zipfile.ZipFile(next(iter(subidos))) as archivo:\n        archivo.extractall(carpeta)\n    for candidata in (carpeta, *(p.parent for p in carpeta.rglob("src/config.py"))):\n        if _sirve(candidata):\n            return candidata\n    return None\n\n\ndef obtener_proyecto() -> Path:\n    # 1. Ya esta aqui: se esta ejecutando dentro del repositorio o junto a un clon\n    aqui = Path.cwd()\n    for candidata in (aqui, *list(aqui.parents)[:2], DESTINO):\n        if _sirve(candidata):\n            return candidata\n\n    # 2. Se clona. Funciona igual en Colab que en un Jupyter local con git e internet\n    clonado = subprocess.run(\n        ["git", "clone", "--depth", "1", REPOSITORIO, str(DESTINO)],\n        capture_output=True, text=True,\n    )\n    if _sirve(DESTINO):\n        print("proyecto clonado del repositorio")\n        return DESTINO\n\n    print("No se pudo clonar: " + clonado.stderr.strip()[:140])\n    if not _en_colab():\n        raise RuntimeError("Clonalo a mano con:  git clone " + REPOSITORIO)\n\n    # 3. Solo en Colab y solo si lo anterior fallo\n    print("Se intenta con Drive, y si no, subiendo un zip.")\n    for alternativa in (_desde_drive, _desde_zip):\n        try:\n            raiz = alternativa()\n        except Exception as error:\n            print("  " + alternativa.__name__ + ": " + str(error)[:100])\n            continue\n        if raiz:\n            return raiz\n    raise RuntimeError("No se pudo obtener el proyecto por ninguna via")\n\n\nRAIZ = obtener_proyecto()\nsys.path.insert(0, str(RAIZ))\nprint("raiz del proyecto: " + RAIZ.name + "/")\n'),
    code('\n# 2/2 - Comprobacion: que este todo lo que el notebook va a leer\nfrom src.config import DATOS_PROCESADOS, FIGURAS\n\nNECESARIOS = (\n    "fragmentos.csv", "fragmentos_topicos.csv", "topicos_etiquetados.csv",\n    "temas_consolidado.csv", "ami_resultados.csv", "calidad_modelo.csv",\n    "cohesion_temas.csv", "dispersion_dimensiones.csv", "sensibilidad_umbral.csv",\n    "temas_baja_masa.csv",\n)\nfaltan = [n for n in NECESARIOS if not (DATOS_PROCESADOS / n).exists()]\nfiguras = len(list(FIGURAS.glob("*.png"))) if FIGURAS.exists() else 0\nprint("datos:", "completos" if not faltan else "FALTAN " + str(faltan))\nprint("figuras:", figuras)\n'),
]
